import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose
def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("'df' must be a pandas DataFrame.")

    if 'group' not in df.columns or 'date' not in df.columns or 'value' not in df.columns:
        raise ValueError("'df' must contain 'group', 'date' and 'value' columns.")

    if not isinstance(freq, str):
        raise ValueError("'freq' must be a valid frequency string.")

    if decomposition_model not in ('additive', 'multiplicative'):
        raise ValueError("'decomposition_model' must be 'additive' or 'multiplicative'.")

    if not pd.api.types.is_numeric_dtype(df['value']):
        raise ValueError("'value' column must contain numeric data.")

    try:
        df = df.copy()
        df['date'] = pd.to_datetime(df['date'])
    except Exception:
        raise ValueError("'date' column must contain valid datetime data.")

    try:
        series = df.set_index('date')['value'].asfreq(freq)
    except Exception:
        raise ValueError("'freq' must be a valid frequency string.")

    decomposition_result = seasonal_decompose(series, model=decomposition_model)

    ax = decomposition_result.plot().gca()

    return decomposition_result, ax
