from bs4 import BeautifulSoup
import pandas as pd
def task_func(url='http://example.com'):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.ConnectionError as e:
        raise ConnectionError(f"Could not connect to URL: {e}")
    except requests.HTTPError as e:
        raise requests.HTTPError(f"HTTP error occurred: {e}")

    try:
        soup = BeautifulSoup(response.text, 'html.parser')
        table = soup.find('table')
        if table is None:
            raise ValueError("No table data found on the page")
    except Exception as e:
        raise ValueError(f"Error parsing the page content: {e}")

    headers = []
    header_row = table.find('tr')
    if header_row:
        ths = header_row.find_all('th')
        if ths:
            headers = [th.get_text(strip=True) for th in ths]

    data = []
    rows = table.find_all('tr')
    for row in rows:
        tds = row.find_all('td')
        if tds:
            data.append([td.get_text(strip=True) for td in tds])

    if not data:
        raise ValueError("No table data found on the page")

    if headers:
        df = pd.DataFrame(data, columns=headers)
    else:
        df = pd.DataFrame(data)

    return df
