    for col in range(columns):
        col_type = choice(DATA_TYPES)
        col_data = []
        for _ in range(rows):
            if col_type == str:
                value = ''.join(choice('abcdefghijklmnopqrstuvwxyz') for _ in range(5))
            elif col_type == int:
                value = np.random.randint(0, 10)
            elif col_type == float:
                value = float(np.random.randint(0, 10))
            elif col_type == list:
                length = np.random.randint(1, 6)
                value = [np.random.randint(0, 10) for _ in range(length)]
            elif col_type == tuple:
                length = np.random.randint(1, 6)
                value = tuple(np.random.randint(0, 10) for _ in range(length))
            elif col_type == dict:
                length = np.random.randint(1, 6)
                value = {np.random.randint(0, 10): np.random.randint(0, 10) for _ in range(length)}
            elif col_type == set:
                length = np.random.randint(1, 6)
                value = set(np.random.randint(0, 10) for _ in range(length))
            col_data.append(value)
        data[f'col{col}'] = col_data
    return pd.DataFrame(data)
