import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist.",
            'failed_files': []
        }

    if not os.path.isdir(dst_folder):
        return {
            'success': False,
            'message': f"Destination folder '{dst_folder}' does not exist.",
            'failed_files': []
        }

    files = glob(os.path.join(src_folder, '*'))
    files = [f for f in files if os.path.isfile(f)]

    for file_path in files:
        filename = os.path.basename(file_path)
        try:
            process = subprocess.Popen(
                ['gzip', file_path],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE
            )
            process.wait()

            if process.returncode != 0:
                failed_files.append(filename)
                continue

            compressed_path = file_path + '.gz'

            if not os.path.exists(compressed_path):
                failed_files.append(filename)
                continue

            shutil.move(compressed_path, os.path.join(dst_folder, filename + '.gz'))
        except Exception:
            failed_files.append(filename)

    if failed_files:
        return {
            'success': False,
            'message': 'Some files failed to compress or move.',
            'failed_files': failed_files
        }

    return {
        'success': True,
        'message': 'All files compressed and moved successfully.',
        'failed_files': []
    }
