from glob import glob

def task_func(directory, string):
    def search(data):
        if isinstance(data, dict):
            for key, value in data.items():
                if key == string or value == string:
                    return True
                if search(value):
                    return True
        elif isinstance(data, list):
            for item in data:
                if item == string or search(item):
                    return True
        else:
            if data == string:
                return True
        return False

