import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"'{script_path}' does not exist.")

    p = subprocess.Popen(['bash', script_path])
    pid = p.pid

    try:
        proc = psutil.Process(pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0, 'Memory Usage': 0}

    cpu_usage = 0
    memory_usage = 0

    start_time = time.time()

    while True:
        if time.time() - start_time > timeout:
            p.terminate()
            break

        try:
            cpu_usage += proc.cpu_percent(interval=0.05)
            memory_usage += proc.memory_info().rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break

        if p.poll() is not None:
            break

    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}
