import re
import pandas as pd
def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy()

    def reverse_matched_words(text):
        words = text.split()
        matched = [w for w in words if re.search(pattern, w)]
        matched_reversed = matched[::-1]
        result = []
        idx = 0
        for w in words:
            if re.search(pattern, w):
                result.append(matched_reversed[idx])
                idx += 1
            else:
                result.append(w)
        return ' '.join(result)

    new_df = df.copy()
    new_df[column_name] = new_df[column_name].apply(reverse_matched_words)
    return new_df
