def task_func(dir_path: str, predicates: list) -> dict:
    path = Path(dir_path)
    if not path.is_dir():
        raise FileNotFoundError(f"The specified directory does not exist or is not a directory: {dir_path}")

    valid_predicates = ['is_file', 'is_dir', 'has_special_chars', 'has_numbers']
    unique_predicates = []
    for p in predicates:
        if p in valid_predicates and p not in unique_predicates:
            unique_predicates.append(p)

    if not unique_predicates:
        raise ValueError("No valid predicates are provided.")

    results = {}
    for item in os.listdir(dir_path):
        item_path = path / item
        checks = {}
        for predicate in unique_predicates:
            if predicate == 'is_file':
                checks[predicate] = item_path.is_file()
            elif predicate == 'is_dir':
                checks[predicate] = item_path.is_dir()
            elif predicate == 'has_special_chars':
                checks[predicate] = bool(re.search(r'\W', item))
            elif predicate == 'has_numbers':
                checks[predicate] = bool(re.search(r'\d', item))
        results[item] = checks

    return results
