import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server.setblocking(False)
    server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server.bind((server_address, server_port))
    server.listen(5)

    inputs = [server]
    outputs = []
    message_queues = {}

    end_time = datetime.now() + timedelta(seconds=run_duration)

    while datetime.now() < end_time and inputs:
        timeout = (end_time - datetime.now()).total_seconds()
        if timeout <= 0:
            break

        readable, writable, exceptional = select.select(
            inputs, outputs, inputs, timeout
        )

        for s in readable:
            if s is server:
                connection, client_address = s.accept()
                connection.setblocking(False)
                inputs.append(connection)
                message_queues[connection] = queue.Queue()
            else:
                try:
                    data = s.recv(buffer_size)
                except Exception:
                    if s in outputs:
                        outputs.remove(s)
                    inputs.remove(s)
                    s.close()
                    del message_queues[s]
                    continue

                if data:
                    response = data.decode() + " " + datetime.now().strftime(
                        "%Y-%m-%d %H:%M:%S"
                    )
                    message_queues[s].put(response.encode())
                    if s not in outputs:
                        outputs.append(s)
                else:
                    if s in outputs:
                        outputs.remove(s)
                    inputs.remove(s)
                    s.close()
                    del message_queues[s]

        for s in writable:
            try:
                next_msg = message_queues[s].get_nowait()
            except queue.Empty:
                outputs.remove(s)
            except KeyError:
                if s in outputs:
                    outputs.remove(s)
            else:
                try:
                    s.send(next_msg)
                except Exception:
                    if s in outputs:
                        outputs.remove(s)
                    if s in inputs:
                        inputs.remove(s)
                    s.close()
                    if s in message_queues:
                        del message_queues[s]

        for s in exceptional:
            if s in inputs:
                inputs.remove(s)
            if s in outputs:
                outputs.remove(s)
            s.close()
            if s in message_queues:
                del message_queues[s]

    server.close()

    return f"Server started on {server_address}:{server_port}. Ran for {run_duration} seconds."
```

