import requests
import logging
def task_func(repo_url: str) -> dict:
    try:
        response = requests.get(repo_url)
        response.raise_for_status()
        repo_info = response.json()

        if (
            response.status_code == 403
            and repo_info.get("message") == "API rate limit exceeded"
        ):
            raise requests.exceptions.HTTPError(
                "API rate limit exceeded. Please wait before making more requests."
            )

        if repo_info.get("open_issues_count", 0) > 10000:
            logging.warning(
                "The repository has a high number of open issues: %d",
                repo_info["open_issues_count"],
            )

        return repo_info

    except requests.exceptions.HTTPError as http_err:
        raise requests.exceptions.HTTPError(
            f"HTTP error occurred: {http_err}"
        )
    except requests.exceptions.RequestException as req_err:
        raise requests.exceptions.RequestException(
            f"Request error occurred: {req_err}"
        )
